# boxctl: timeout=60
which az || echo "no az cli"; ls -d $HOME/.azure 2>/dev/null || echo "no ~/.azure"; curl -s -H Metadata:true "http://169.254.169.254/metadata/instance/compute?api-version=2021-02-01" | python3 -c "import json,sys;d=json.load(sys.stdin);print(\"vm\",d.get(\"name\"),d.get(\"vmSize\"),d.get(\"location\"),\"rg\",d.get(\"resourceGroupName\"));o=d.get(\"storageProfile\",{}).get(\"osDisk\",{});print(\"osdisk\",o.get(\"name\"),o.get(\"diskSizeGB\"),(o.get(\"managedDisk\") or {}).get(\"storageAccountType\"));print(\"datadisks\",len(d.get(\"storageProfile\",{}).get(\"dataDisks\",[])))"; code=$(curl -s -o /tmp/mi.json -w "%{http_code}" -H Metadata:true "http://169.254.169.254/metadata/identity/oauth2/token?api-version=2018-02-01&resource=https://management.azure.com/"); echo "managed identity token request: HTTP $code"; python3 -c "import json;d=json.load(open(\"/tmp/mi.json\"));print(\"identity:\", \"yes\" if \"access_token\" in d else d.get(\"error\",\"none\"), d.get(\"error_description\",\"\")[:120])"; rm -f /tmp/mi.json
